import { useState } from "react";

function PostForm({ token, onPostAdded, categoryId }) {
    const [title, setTitle] = useState("");
    const [content, setContent] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!title || !content || !categoryId) {
            setError("Заповніть всі поля та оберіть категорію");
            return;
        }

        setLoading(true);
        try {
            const res = await fetch("http://localhost:5000/api/posts", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ title, content, category_id: categoryId }),
            });

            const data = await res.json();

            if (!res.ok) {
                setError(data.message || "Помилка при створенні поста");
            } else {
                setTitle("");
                setContent("");
                setError("");
                onPostAdded();
            }
        } catch (err) {
            console.error(err);
            setError("Помилка при запиті до сервера");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="card-gradient rounded-2xl p-6 shadow-xl">
            <h3 className="text-xl font-bold mb-4">Створити пост</h3>
            {error && <p className="text-red-500 mb-2">{error}</p>}
            <form onSubmit={handleSubmit} className="space-y-3">
                <input
                    type="text"
                    placeholder="Заголовок поста..."
                    value={title}
                    onChange={e => setTitle(e.target.value)}
                    className="input-field w-full"
                />
                <textarea
                    placeholder="Текст поста..."
                    value={content}
                    onChange={e => setContent(e.target.value)}
                    className="input-field w-full"
                    rows={4}
                />
                <button
                    type="submit"
                    disabled={loading}
                    className="btn-primary w-full disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? "Публікуємо..." : "Опублікувати"}
                </button>
            </form>
        </div>
    );
}

export default PostForm;
